js:
var closeBtn = root.querySelector('.fb10-banner-dismiss-x');
var restore = root.querySelector('.fb10-banner-dismiss-restore');
var cta = root.querySelector('.fb10-banner-dismiss-cta');
var OUT = 'fb10-banner-dismiss-out';
var t = 0, ct = 0;
function hide(){
  clearTimeout(t);
  root.classList.add(OUT);
  t = setTimeout(function(){
    restore.hidden = false;
    restore.focus({ preventScroll: true });
  }, 380);
}
function show(){
  clearTimeout(t);
  restore.hidden = true;
  root.classList.remove(OUT);
  closeBtn.focus({ preventScroll: true });
}
closeBtn.addEventListener('click', hide);
restore.addEventListener('click', show);
cta.addEventListener('click', function(){
  clearTimeout(ct);
  cta.disabled = true;
  cta.textContent = 'Opening...';
  ct = setTimeout(function(){ cta.disabled = false; cta.textContent = 'Manage'; }, 900);
});

