js:
var list = root.querySelector('.fb10-toast-stack-list');
var addBtn = root.querySelector('.fb10-toast-stack-add');
var count = root.querySelector('.fb10-toast-stack-count');
var MAX = 3, LIFE = 3600, seq = 0;
var DATA = [
  ['ok', 'Repo synced', '42 files in 1.2s'],
  ['info', 'Invite sent', 'dana@northwind.co'],
  ['warn', 'Webhook retried', 'attempt 2 of 3'],
  ['ok', 'Draft autosaved', 'a moment ago'],
  ['info', 'Export ready', 'events-aug.csv']
];
var ICON = {
  ok: '<path d="M3.4 8.4l3 3 6.4-7"/>',
  info: '<circle cx="8" cy="8" r="6.3"/><path d="M8 7.4v3.4"/><path d="M8 5.1h.01"/>',
  warn: '<path d="M8 2.7l6.2 10.6H1.8L8 2.7z"/><path d="M8 6.8v2.9"/><path d="M8 11.5h.01"/>'
};
function live(){
  var out = [], c = list.children, i;
  for (i = 0; i < c.length; i++) { if (c[i].getAttribute('data-gone') !== '1') out.push(c[i]); }
  return out;
}
function layout(){
  var a = live(), n = a.length, i, d, el;
  for (i = 0; i < n; i++) {
    el = a[i]; d = n - 1 - i;
    el.style.zIndex = String(40 - d);
    el.style.transform = 'translateY(' + (-d * 7) + 'px) scale(' + (1 - d * 0.055).toFixed(3) + ')';
    el.style.opacity = String(Math.max(0, 1 - d * 0.24));
  }
  count.textContent = n === 0 ? 'idle' : n + ' active';
  if (n === 0) root.classList.add('fb10-toast-stack-empty');
  else root.classList.remove('fb10-toast-stack-empty');
}
function dismiss(el){
  if (!el || el.getAttribute('data-gone') === '1') return;
  el.setAttribute('data-gone', '1');
  if (el.fb10Timer) { clearTimeout(el.fb10Timer); el.fb10Timer = 0; }
  el.style.transform = 'translateX(114%) scale(.94)';
  el.style.opacity = '0';
  setTimeout(function(){ if (el.parentNode) el.parentNode.removeChild(el); layout(); }, 340);
  layout();
}
function push(){
  var d = DATA[seq % DATA.length];
  seq++;
  var el = document.createElement('li');
  el.className = 'fb10-toast-stack-item';
  el.setAttribute('data-kind', d[0]);
  el.innerHTML = '<span class="fb10-toast-stack-ico" aria-hidden="true"><svg class="fb10-toast-stack-svg" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + ICON[d[0]] + '</svg></span>' +
    '<span class="fb10-toast-stack-copy"><span class="fb10-toast-stack-t">' + d[1] + '</span><span class="fb10-toast-stack-s">' + d[2] + '</span></span>' +
    '<button class="fb10-toast-stack-x" type="button" aria-label="Dismiss notification"><svg class="fb10-toast-stack-svg" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M4.6 4.6l6.8 6.8M11.4 4.6l-6.8 6.8"/></svg></button>' +
    '<span class="fb10-toast-stack-life" aria-hidden="true"></span>';
  el.style.transform = 'translateY(30px) scale(.86)';
  el.style.opacity = '0';
  list.appendChild(el);
  el.querySelector('.fb10-toast-stack-x').addEventListener('click', function(){ dismiss(el); });
  var a = live();
  if (a.length > MAX) dismiss(a[0]);
  requestAnimationFrame(function(){ requestAnimationFrame(layout); });
  el.fb10Timer = setTimeout(function(){ dismiss(el); }, LIFE);
}
addBtn.addEventListener('click', push);
push();
setTimeout(push, 750);

