var input = root.querySelector('.fb10-field-shake-input');
var msg = root.querySelector('.fb10-field-shake-msg');
var submit = root.querySelector('.fb10-field-shake-submit');
function problem(v){
  v = v.replace(/^\s+|\s+$/g, '');
  if (!v) return 'Enter your work email to continue.';
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v)) return 'That does not look like an email address.';
  if (/@(gmail|yahoo|hotmail|outlook|icloud|proton)\./i.test(v)) return 'Use your work email, personal domains are not supported.';
  return '';
}
function idle(){
  root.setAttribute('data-state', 'idle');
  root.removeAttribute('data-shake');
  input.setAttribute('aria-invalid', 'false');
  msg.textContent = '';
  submit.textContent = 'Continue';
}
root.addEventListener('submit', function(e){
  e.preventDefault();
  var bad = problem(input.value);
  if (bad) {
    root.setAttribute('data-state', 'error');
    input.setAttribute('aria-invalid', 'true');
    msg.textContent = bad;
    root.removeAttribute('data-shake');
    void root.offsetWidth;
    root.setAttribute('data-shake', '1');
    input.focus({ preventScroll: true });
    return;
  }
  root.setAttribute('data-state', 'ok');
  root.removeAttribute('data-shake');
  input.setAttribute('aria-invalid', 'false');
  msg.textContent = 'Verified, we sent a confirmation link.';
  submit.textContent = 'Verified';
});
input.addEventListener('input', function(){
  if (root.getAttribute('data-state') !== 'idle') idle();
});

