var btn = root.querySelector('.fb10-offline-pulse-sim');
var st = root.querySelector('.fb10-offline-pulse-status');
var de = root.querySelector('.fb10-offline-pulse-detail');
var outs = [], ivs = [];
function clearAll(){
  var i;
  for (i = 0; i < outs.length; i++) clearTimeout(outs[i]);
  for (i = 0; i < ivs.length; i++) clearInterval(ivs[i]);
  outs = []; ivs = [];
}
function goOnline(){
  clearAll();
  root.setAttribute('data-state', 'online');
  st.textContent = 'Connected';
  de.textContent = 'Realtime sync · 24 ms';
  btn.textContent = 'Simulate drop';
}
function goRetry(){
  clearAll();
  var n = 3;
  root.setAttribute('data-state', 'retry');
  st.textContent = 'Reconnecting';
  de.textContent = 'Attempt 2 of 5 · retrying in ' + n + 's';
  var iv = setInterval(function(){
    n--;
    if (n <= 0) { goOnline(); return; }
    de.textContent = 'Attempt 2 of 5 · retrying in ' + n + 's';
  }, 1000);
  ivs.push(iv);
}
function goOffline(){
  clearAll();
  root.setAttribute('data-state', 'offline');
  st.textContent = 'You are offline';
  de.textContent = '3 changes queued locally';
  btn.textContent = 'Retry now';
  outs.push(setTimeout(goRetry, 1500));
}
btn.addEventListener('click', function(){
  if (root.getAttribute('data-state') === 'online') goOffline();
  else goOnline();
});

