.fb10-undo-snackbar-timer{position:relative;width:20px;height:20px;flex:none;display:block}
.fb10-undo-snackbar-ring{width:20px;height:20px;display:block}
.fb10-undo-snackbar-num{position:absolute;left:0;top:0;right:0;bottom:0;display:grid;place-items:center;font-size:9px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--fb10us-c)}
.fb10-undo-snackbar-bar[data-paused="1"] .fb10-undo-snackbar-num{opacity:.55}
.fb10-undo-snackbar-bar[data-paused="1"] .fb10-undo-snackbar-undo{background:rgba(246,180,76,.2)}
@keyframes fb10us-rise{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){
.fb10-undo-snackbar .fb10-undo-snackbar-bar{transition-duration:.01ms}
.fb10-undo-snackbar .fb10-undo-snackbar-bar[data-open="true"]{transition-duration:.01ms}
.fb10-undo-snackbar .fb10-undo-snackbar-echo[data-in="1"]{animation-duration:.01ms}
.fb10-undo-snackbar .fb10-undo-snackbar-trigger,.fb10-undo-snackbar .fb10-undo-snackbar-undo{transition-duration:.01ms}
}

js:
var trigger = root.querySelector('.fb10-undo-snackbar-trigger');
var bar = root.querySelector('.fb10-undo-snackbar-bar');
var undo = root.querySelector('.fb10-undo-snackbar-undo');
var arc = root.querySelector('.fb10-undo-snackbar-arc');
var num = root.querySelector('.fb10-undo-snackbar-num');
var echo = root.querySelector('.fb10-undo-snackbar-echo');
var C = 56.55, DUR = 5000;
var remain = DUR, last = 0, raf = 0, open = false, paused = false;
function paint(){
  var left = remain > 0 ? remain : 0;
  arc.setAttribute('stroke-dashoffset', (C * (1 - left / DUR)).toFixed(2));
  num.textContent = String(Math.max(1, Math.ceil(left / 1000)));
}
function frame(ts){
  if (!open) return;
  if (!last) last = ts;
  var dt = ts - last;
  last = ts;
  if (!paused) remain -= dt;
  if (remain <= 0) { finish('expired'); return; }
  paint();
  raf = requestAnimationFrame(frame);
}
function finish(kind){
  open = false;
  if (raf) cancelAnimationFrame(raf);
  raf = 0; last = 0; paused = false;
  bar.setAttribute('data-open', 'false');
  bar.removeAttribute('data-paused');
  echo.textContent = kind === 'undo' ? 'Restored to Inbox, nothing was archived.' : 'Archived, 1 thread moved.';
  echo.setAttribute('data-kind', kind === 'undo' ? 'undo' : 'done');
  echo.removeAttribute('data-in');
  void echo.offsetWidth;
  echo.setAttribute('data-in', '1');
  if (kind === 'undo') trigger.focus({ preventScroll: true });
}
trigger.addEventListener('click', function(){
  if (open) return;
  open = true; paused = false; remain = DUR; last = 0;
  echo.textContent = '';
  echo.removeAttribute('data-in');
  paint();
  bar.setAttribute('data-open', 'true');
  raf = requestAnimationFrame(frame);
});
undo.addEventListener('click', function(){ if (open) finish('undo'); });
function hold(){ if (open) { paused = true; bar.setAttribute('data-paused', '1'); } }
function release(){ paused = false; bar.removeAttribute('data-paused'); }
bar.addEventListener('pointerenter', hold);
bar.addEventListener('pointerleave', release);
bar.addEventListener('focusin', hold);
bar.addEventListener('focusout', release);
